/bin/bash -lc "python3 - <<'PY'
import cv2, numpy as np
im=cv2.imread('first_frame.png'); hsv=cv2.cvtColor(im,cv2.COLOR_BGR2HSV)
# summarize grid by mean brightness and saturation, 16x9 cells
for kind,a in [('V',hsv[:,:,2]),('S',hsv[:,:,1]),('H',hsv[:,:,0])]:
 print('\\n',kind)
 for yy in range(9):
  vals=[]
  for xx in range(16): vals.append(int(np.mean(a[yy*16:(yy+1)*16,xx*16:(xx+1)*16])))
  print(' '.join(f'{v:3d}' for v in vals))
# components for saturated likely balls
for name,mask in [
 ('sat>80',(hsv[:,:,1]>80).astype('uint8')),
 ('orange',( ((hsv[:,:,0]<30)|(hsv[:,:,0]>170)) & (hsv[:,:,1]>80)&(hsv[:,:,2]>40)).astype('uint8')),
 ('dark',(hsv[:,:,2]<35).astype('uint8'))]:
 n,lab,st,cen=cv2.connectedComponentsWithStats(mask)
 print('\\n',name)
 for i in np.argsort(st[1:,4])[-20:][::-1]+1:
  x,y,w,h,area=st[i];
  if area>5: print(area,(x,y,w,h),cen[i])
# Print color stats around likely central areas and high sat bounding per rows
print('\\n sat ranges rows')
for y in range(0,144,4):
 xs=np.where((hsv[y,:,1]>100)&(hsv[y,:,2]>30))[0]
 if len(xs): print(y,len(xs),xs.min(),xs.max())
PY"
